package com.rulecraft.decisionops.simulation.domain;

import com.rulecraft.decisionops.tests.domain.DecisionTestCase;import com.rulecraft.decisionops.tests.DecisionTestService.TestRunView;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;

@Entity @Table(name="regression_matrix_result")
public class RegressionMatrixResult {
    @Id private UUID id;@Column(name="matrix_run_id",nullable=false)private UUID matrixRunId;@Column(nullable=false)private int position;@Column(name="test_case_id",nullable=false)private UUID testCaseId;@Column(name="test_case_version",nullable=false)private long testCaseVersion;@Column(name="test_key",nullable=false,length=60)private String testKey;@Column(name="test_name",nullable=false,length=160)private String testName;
    @Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private MatrixCaseStatus status;@Column(name="test_run_id")private UUID testRunId;@Column(name="evaluation_id")private UUID evaluationId;@Column(name="graph_version")private Long graphVersion;@Column(name="expected_outputs_json",nullable=false,columnDefinition="text")private String expectedOutputsJson;@Column(name="actual_outputs_json",columnDefinition="text")private String actualOutputsJson;@Column(name="decision_results_json",columnDefinition="text")private String decisionResultsJson;@Column(name="error_code",length=80)private String errorCode;@Column(name="error_detail",length=500)private String errorDetail;@Column(name="executed_at",nullable=false)private Instant executedAt;
    protected RegressionMatrixResult(){}
    public static RegressionMatrixResult completed(UUID matrixId,int position,DecisionTestCase test,TestRunView run,String expected,String actual,String decisions,Instant now){var value=base(matrixId,position,test,now);value.testCaseVersion=run.testCaseVersion();value.status=run.status().name().equals("PASSED")?MatrixCaseStatus.PASSED:MatrixCaseStatus.FAILED;value.testRunId=run.id();value.evaluationId=run.evaluationId();value.graphVersion=run.graphVersion();value.expectedOutputsJson=expected;value.actualOutputsJson=actual;value.decisionResultsJson=decisions;return value;}
    public static RegressionMatrixResult error(UUID matrixId,int position,DecisionTestCase test,String expected,String code,String detail,Instant now){var value=base(matrixId,position,test,now);value.status=MatrixCaseStatus.ERROR;value.expectedOutputsJson=expected;value.errorCode=code;value.errorDetail=detail;return value;}
    private static RegressionMatrixResult base(UUID matrixId,int position,DecisionTestCase test,Instant now){var value=new RegressionMatrixResult();value.id=UUID.randomUUID();value.matrixRunId=matrixId;value.position=position;value.testCaseId=test.getId();value.testCaseVersion=test.getVersion();value.testKey=test.getTestKey();value.testName=test.getName();value.executedAt=now;return value;}
    public UUID getId(){return id;}public UUID getMatrixRunId(){return matrixRunId;}public int getPosition(){return position;}public UUID getTestCaseId(){return testCaseId;}public long getTestCaseVersion(){return testCaseVersion;}public String getTestKey(){return testKey;}public String getTestName(){return testName;}public MatrixCaseStatus getStatus(){return status;}public UUID getTestRunId(){return testRunId;}public UUID getEvaluationId(){return evaluationId;}public Long getGraphVersion(){return graphVersion;}public String getExpectedOutputsJson(){return expectedOutputsJson;}public String getActualOutputsJson(){return actualOutputsJson;}public String getDecisionResultsJson(){return decisionResultsJson;}public String getErrorCode(){return errorCode;}public String getErrorDetail(){return errorDetail;}public Instant getExecutedAt(){return executedAt;}
}
